test('bhv authbearer 006 every generated bearer wrapper sends the bearer header and masks the token', function (): void {
    $wrappers = 0;
    foreach (glob(__DIR__ . '/../lib/Auth/*Authenticator.php') ?: [] as $file) {
        $class = 'PetstoreClient\\Auth\\' . basename($file, '.php');
        if (!is_subclass_of($class, BearerAuthenticator::class)) {
            continue;
        }
        $wrappers++;
        $reflection = new \ReflectionClass($class);

        $auth = $reflection->newInstance('https://api.example.com', 'wrapper-token');
        expect($auth->getAuthHeaders())->toBe(['Authorization' => 'Bearer wrapper-token']);
        expect(print_r($auth, true))->not->toContain('wrapper-token');
        expect(fn () => $reflection->newInstance('https://api.example.com', ''))
            ->toThrow(\InvalidArgumentException::class);
    }
    expect($wrappers)->toBeGreaterThan(0);
});

/**
 * Runs $body with the token environment variable of PetStoreBearerAuthenticator set to $value (null unsets it), then restores it.
 */
function withBearerTokenEnvironment(?string $value, callable $body): void
{
    $name = 'SWAGGER_PETSTORE_OPEN_API_3_0_PET_STORE_BEARER_TOKEN';
    $previous = getenv($name);
    putenv($value === null ? $name : $name . '=' . $value);
    try {
        $body();
    } finally {
        putenv($previous === false ? $name : $name . '=' . $previous);
    }
}

